<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hostels - DormSync</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb;text-decoration:none}main{max-width:1100px;margin:auto;padding:36px 24px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:22px;margin-bottom:20px}label{display:block;font-size:13px;font-weight:600;margin:12px 0 6px}input,select,button{padding:10px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}input,select{width:100%}button{background:#2563eb;color:#fff;border-color:#2563eb;cursor:pointer}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #e7ebf2;padding:11px;text-align:left;font-size:13px}.message{padding:10px;background:#dcfce7;color:#166534;margin-bottom:12px}.error{background:#fee2e2;color:#991b1b}.form-grid{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px;align-items:end}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.table-wrap{overflow:auto}table{min-width:650px}}</style></head><body><header class="topbar"><a href="/admin/dashboard">Back to dashboard</a></header><main><h1>Hostel management</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="message error"><?=htmlspecialchars($error)?></div><?php endif;?><?php foreach($errors as $fieldErrors):foreach((array)$fieldErrors as $item):?><div class="message error"><?=htmlspecialchars($item)?></div><?php endforeach;endforeach;?><section class="panel"><h2>Add hostel</h2><form method="post" action="/admin/hostel-store" class="form-grid"><div><label>Name</label><input name="name" required></div><div><label>Block code</label><input name="block" required></div><div><label>Status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><button type="submit">Add</button></form></section><section class="panel"><h2>Existing hostels</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Block</th><th>Rooms</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if($hostels):foreach($hostels as $hostel):?><tr><form method="post" action="/admin/hostel/<?= (int)$hostel['id'] ?>"><td><input name="name" value="<?=htmlspecialchars($hostel['name'])?>" required></td><td><input name="block" value="<?=htmlspecialchars($hostel['block'])?>" required></td><td><?= (int)$hostel['room_count']?></td><td><select name="status"><option value="active" <?=$hostel['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$hostel['status']==='inactive'?'selected':''?>>Inactive</option></select></td><td><button type="submit">Save</button></td></form></tr><?php endforeach;else:?><tr><td colspan="5">No hostels created.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
